CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id = (select auth.uid()));
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = (select auth.uid()));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = (select auth.uid())) WITH CHECK (id = (select auth.uid()));
CREATE TABLE public.study_workspaces (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{"version":1,"subjects":[{"id":"s1","name":"Tamil","color":0},{"id":"s2","name":"English","color":1},{"id":"s3","name":"Mathematics","color":2},{"id":"s4","name":"Physics","color":3},{"id":"s5","name":"Chemistry","color":4},{"id":"s6","name":"Computer Science","color":5}],"chapters":[],"tasks":[],"events":[],"blocks":[],"sessions":[],"progressHistory":[],"settings":{"name":"","theme":"system","notifications":false,"focusMin":25,"breakMin":5,"longBreakMin":15}}'::jsonb, revision integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.study_workspaces TO authenticated;
GRANT ALL ON public.study_workspaces TO service_role;
ALTER TABLE public.study_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_read ON public.study_workspaces FOR SELECT TO authenticated USING (user_id = (select auth.uid()));
CREATE POLICY workspace_update ON public.study_workspaces FOR UPDATE TO authenticated USING (user_id = (select auth.uid())) WITH CHECK (user_id = (select auth.uid()));
CREATE FUNCTION public.create_study_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name','')); INSERT INTO public.study_workspaces(user_id) VALUES (NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER create_study_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_study_account();
CREATE FUNCTION public.save_study_workspace(expected_revision integer, next_data jsonb) RETURNS SETOF public.study_workspaces LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$ BEGIN RETURN QUERY UPDATE public.study_workspaces SET data = next_data, revision = expected_revision + 1, updated_at = now() WHERE user_id = (select auth.uid()) AND revision = expected_revision RETURNING *; END; $$;
REVOKE ALL ON FUNCTION public.save_study_workspace(integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_study_workspace(integer,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.create_study_account() FROM PUBLIC;